import { lookup } from "node:dns/promises";
import { once } from "node:events";
import { createServer, type IncomingHttpHeaders, request } from "node:http";
import { connect, type LookupFunction, type Socket } from "node:net";
import type { ScraperAccessPolicy } from "../../utils/accessPolicy";
import { AccessPolicyError } from "../../utils/errors";

/** Marks a rejection generated by the loopback proxy. */
export const PROXY_POLICY_HEADER = "x-grounded-docs-network-denied";

function forwardHeaders(headers: IncomingHttpHeaders): IncomingHttpHeaders {
  const excluded = new Set([
    "connection",
    "keep-alive",
    "proxy-authenticate",
    "proxy-authorization",
    "proxy-connection",
    "te",
    "trailer",
    "transfer-encoding",
    "upgrade",
    PROXY_POLICY_HEADER,
    ...String(headers.connection ?? "")
      .toLowerCase()
      .split(/\s*,\s*/),
  ]);
  return Object.fromEntries(
    Object.entries(headers).filter(([name]) => !excluded.has(name)),
  );
}

/**
 * Routes Obscura's HTTP requests and HTTPS tunnels through the scraper policy.
 * Obscura follows redirects inside its own HTTP client, past Playwright's routes.
 *
 * @param policy - The same outbound policy used by the scraper's other clients.
 * @returns The loopback proxy URL and its shutdown function.
 */
export async function startObscuraProxy(
  policy: ScraperAccessPolicy,
): Promise<{ url: string; close: () => void }> {
  const sockets = new Set<Socket>();
  let proxyPort = 0;
  let closed = false;

  async function resolveTarget(
    url: URL,
  ): Promise<{ host: string; lookup: LookupFunction }> {
    const host = url.hostname.replace(/^\[(.*)]$/, "$1");
    const addresses = await lookup(host, { all: true });
    await policy.assertNetworkUrlAllowed(url.href, addresses);
    if (Number(url.port) === proxyPort) {
      throw new AccessPolicyError(
        "Security policy blocked access to the browser proxy port",
      );
    }
    const first = addresses[0];
    if (!first) throw new Error(`No address for ${host}`);

    return {
      host,
      lookup: (_hostname, options, callback) => {
        if (options.all) callback(null, addresses);
        else callback(null, first.address, first.family);
      },
    };
  }

  const server = createServer(async (incoming, outgoing) => {
    try {
      const url = new URL(incoming.url ?? "");
      if (url.protocol !== "http:" || url.username || url.password) {
        outgoing.writeHead(400).end();
        return;
      }
      const target = await resolveTarget(url);
      if (outgoing.destroyed) return;

      const upstream = request({
        ...target,
        port: url.port || 80,
        path: url.pathname + url.search,
        method: incoming.method,
        headers: { ...forwardHeaders(incoming.headers), host: url.host },
        agent: false,
      });
      upstream.on("response", (response) => {
        outgoing.writeHead(response.statusCode ?? 502, forwardHeaders(response.headers));
        response.on("error", () => outgoing.destroy());
        response.pipe(outgoing);
      });
      upstream.on("error", () => {
        if (outgoing.headersSent) outgoing.destroy();
        else outgoing.writeHead(502).end();
      });
      outgoing.on("close", () => upstream.destroy());
      incoming.pipe(upstream);
    } catch (error) {
      if (outgoing.destroyed) return;
      if (error instanceof AccessPolicyError) {
        outgoing.writeHead(403, { [PROXY_POLICY_HEADER]: "1" }).end();
      } else {
        outgoing.writeHead(502).end();
      }
    }
  });

  server.on("connect", async (incoming, client, head) => {
    client.on("error", () => client.destroy());
    try {
      const authority = incoming.url ?? "";
      if (!/^(?:\[[\da-f:.]+\]|[^/?#:@\\\s]+):\d+$/i.test(authority)) {
        client.end("HTTP/1.1 400 Bad Request\r\nConnection: close\r\n\r\n");
        return;
      }
      const url = new URL(`https://${authority}`);
      const target = await resolveTarget(url);
      if (client.destroyed) return;

      const upstream = connect({ ...target, port: Number(url.port || 443) });
      client.on("close", () => upstream.destroy());
      upstream.on("error", () => client.destroy());
      upstream.on("connect", () => {
        client.write("HTTP/1.1 200 Connection Established\r\n\r\n");
        upstream.write(head);
        client.pipe(upstream).pipe(client);
      });
    } catch (error) {
      const status =
        error instanceof AccessPolicyError ? "403 Forbidden" : "502 Bad Gateway";
      client.end(`HTTP/1.1 ${status}\r\nConnection: close\r\n\r\n`);
    }
  });

  server.on("connection", (socket) => {
    sockets.add(socket);
    socket.once("close", () => sockets.delete(socket));
  });
  await once(server.listen(0, "127.0.0.1"), "listening");
  const address = server.address();
  if (!address || typeof address === "string") {
    server.close();
    throw new Error("Obscura proxy did not bind a TCP port");
  }
  proxyPort = address.port;

  return {
    url: `http://127.0.0.1:${proxyPort}`,
    close: () => {
      if (closed) return;
      closed = true;
      server.close();
      for (const socket of sockets) socket.destroy();
    },
  };
}
